  outgoing={'Content-Type':'application/json',**(headers or {})}
  if tenant is not None:outgoing['X-Scope-OrgID']=tenant
  request=urllib.request.Request(self.base+path,data=None if data is None else json.dumps(data,ensure_ascii=False).encode(),headers=outgoing)
  with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(request,timeout=3) as response:
   raw=response.read();return json.loads(raw) if raw and 'json' in response.headers.get('Content-Type','') else raw
 def wait(self,predicate,description,seconds=5):
  deadline=time.monotonic()+seconds
  while time.monotonic()<deadline:
   if self.process.poll() is not None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Loki exited: '+(self.root/'server.log').read_text(errors='replace')[-2500:])
   try:
    value=predicate()
    if value:return value
   except (OSError,urllib.error.URLError):pass
   time.sleep(.04)
  raise AssertionError('native Loki deadline: '+description)
 def push(self,streams,tenant=None):
  result=self.request('/loki/api/v1/push',{'streams':streams},tenant=tenant);assert result==b''
