def export_audit(query,start,end,page_limit,max_limit,destination):
    if any(type(x) is not int for x in (start,end,page_limit,max_limit)) or not 0<=start<end or not 1<=page_limit<=max_limit<=1000:raise ValueError('bounded half-open query window')
    destination=pathlib.Path(destination)
    if destination.exists():raise FileExistsError(destination)
    calls=0
    def fetch(lo,hi):
        nonlocal calls
        limit=page_limit
        while True:
            calls+=1
            if calls>256:raise RuntimeError('incomplete: query budget exceeded')
            rows=query(lo,hi,limit)
            if len(rows)<limit:return rows
            if limit<max_limit:limit=min(max_limit,limit*2);continue
            if hi-lo==1:raise RuntimeError('incomplete: saturated timestamp cannot be proven complete')
            middle=(lo+hi)//2
            return fetch(lo,middle)+fetch(middle,hi)
    rows=fetch(start,end)
    if len(rows)>20000:raise RuntimeError('incomplete: output memory budget exceeded')
    rows.sort(key=lambda row:(row['timestamp'],json.dumps(row['labels'],sort_keys=True),row['line']))
    with destination.open('x',encoding='utf8') as stream:
        for row in rows:stream.write(json.dumps(row,ensure_ascii=False,sort_keys=True)+'\n')
    return {'complete':True,'rows':len(rows)}
